package forth

import (
	"fmt"
	"strconv"
	"strings"
)

// op is a single executable step: either a built-in behavior or
// the push of a number literal.
type op func(*vm) error

// word is a defined Forth word. Its body is a list of steps,
// expanded at definition time so that words referenced by a
// definition keep the meaning they had when it was created.
type word struct {
	body []op
}

func (w *word) exec(v *vm) error {
	for _, step := range w.body {
		if err := step(v); err != nil {
			return err
		}
	}
	return nil
}

// vm is the state of the evaluator: the data stack and the
// dictionary of defined words (built-ins plus user definitions).
type vm struct {
	stack []int
	defs  map[string]*word
}

func newVM() *vm {
	return &vm{
		defs: map[string]*word{
			"+":    {body: []op{binop(func(a, b int) int { return a + b })}},
			"-":    {body: []op{binop(func(a, b int) int { return a - b })}},
			"*":    {body: []op{binop(func(a, b int) int { return a * b })}},
			"/":    {body: []op{div}},
			"dup":  {body: []op{dup}},
			"drop": {body: []op{drop}},
			"swap": {body: []op{swap}},
			"over": {body: []op{over}},
		},
	}
}

// Forth evaluates the given input lines in order, sharing a single
// evaluator, and returns the resulting data stack.
func Forth(input []string) ([]int, error) {
	v := newVM()
	for _, line := range input {
		tokens := strings.Fields(line)
		for i := 0; i < len(tokens); i++ {
			if tokens[i] != ":" {
				if err := v.execToken(tokens[i]); err != nil {
					return nil, err
				}
				continue
			}
			// A word definition: : name body ;
			i++
			if i >= len(tokens) {
				return nil, fmt.Errorf("malformed definition: missing word name")
			}
			name := strings.ToLower(tokens[i])
			if _, isNum := parseNumber(name); isNum {
				return nil, fmt.Errorf("illegal operation: cannot define %q", name)
			}
			i++
			body := []string{}
			for ; i < len(tokens); i++ {
				if tokens[i] == ";" {
					break
				}
				body = append(body, strings.ToLower(tokens[i]))
			}
			w, err := v.compile(body)
			if err != nil {
				return nil, err
			}
			v.defs[name] = w
		}
	}
	if v.stack == nil {
		v.stack = []int{}
	}
	return v.stack, nil
}

// execToken executes a single token: a number is pushed, anything
// else must be a defined word.
func (v *vm) execToken(tok string) error {
	if n, ok := parseNumber(tok); ok {
		v.push(n)
		return nil
	}
	w, ok := v.defs[strings.ToLower(tok)]
	if !ok {
		return fmt.Errorf("undefined operation: %q", tok)
	}
	return w.exec(v)
}

// compile turns the raw tokens of a definition body into steps.
// References to already-defined words are expanded into those
// words' current bodies, so a definition captures the meaning of
// the words it uses at the time it is defined.
func (v *vm) compile(tokens []string) (*word, error) {
	body := []op{}
	for _, tok := range tokens {
		if n, ok := parseNumber(tok); ok {
			body = append(body, pusher(n))
			continue
		}
		w, ok := v.defs[strings.ToLower(tok)]
		if !ok {
			return nil, fmt.Errorf("undefined word in definition: %q", tok)
		}
		body = append(body, w.body...)
	}
	return &word{body: body}, nil
}

// pusher returns an op that pushes n onto the stack.
func pusher(n int) op {
	return func(v *vm) error {
		v.push(n)
		return nil
	}
}

// parseNumber reports whether tok is a (possibly negative) integer
// literal: an optional '-' followed by one or more digits.
func parseNumber(tok string) (int, bool) {
	i := 0
	if tok == "" {
		return 0, false
	}
	if tok[0] == '-' {
		i = 1
	}
	if i >= len(tok) {
		return 0, false
	}
	for ; i < len(tok); i++ {
		if c := tok[i]; c < '0' || c > '9' {
			return 0, false
		}
	}
	n, err := strconv.Atoi(tok)
	if err != nil {
		return 0, false
	}
	return n, true
}

func (v *vm) push(n int) {
	v.stack = append(v.stack, n)
}

func (v *vm) pop() (int, error) {
	if len(v.stack) == 0 {
		return 0, fmt.Errorf("empty stack")
	}
	n := v.stack[len(v.stack)-1]
	v.stack = v.stack[:len(v.stack)-1]
	return n, nil
}

// binop pops two values (top is b) and pushes f(a, b).
func binop(f func(a, b int) int) op {
	return func(v *vm) error {
		b, err := v.pop()
		if err != nil {
			return err
		}
		a, err := v.pop()
		if err != nil {
			return err
		}
		v.push(f(a, b))
		return nil
	}
}

func div(v *vm) error {
	b, err := v.pop()
	if err != nil {
		return err
	}
	a, err := v.pop()
	if err != nil {
		return err
	}
	if b == 0 {
		return fmt.Errorf("divide by zero")
	}
	v.push(a / b)
	return nil
}

func dup(v *vm) error {
	a, err := v.pop()
	if err != nil {
		return err
	}
	v.push(a)
	v.push(a)
	return nil
}

func drop(v *vm) error {
	_, err := v.pop()
	return err
}

func swap(v *vm) error {
	b, err := v.pop()
	if err != nil {
		return err
	}
	a, err := v.pop()
	if err != nil {
		return err
	}
	v.push(b)
	v.push(a)
	return nil
}

func over(v *vm) error {
	b, err := v.pop()
	if err != nil {
		return err
	}
	a, err := v.pop()
	if err != nil {
		return err
	}
	v.push(a)
	v.push(b)
	v.push(a)
	return nil
}

